def reverse_text(text: str) -> dict:
    """Reverse the characters of a piece of text."""
    return {"reversed": text[::-1]}

TOOL_IMPLS["reverse_text"] = reverse_text
TOOLS.append({
    "type": "function",
    "function": {
        "name": "reverse_text",
        "description": "Reverse the characters of the given text. Use when the user asks to reverse text.",
        "parameters": {
            "type": "object",
            "properties": {"text": {"type": "string", "description": "Text to reverse."}},
            "required": ["text"],
        },
    },
})

if __name__ == "__main__":
    print(run_agent(
        "Reverse the text 'agent' and then tell me how many words are in the reversed result."
    ))
